from collections import Counter

def maxSubarrayLength(nums, k):
    n = len(nums)
    freq = Counter()
    start = 0
    violations = 0

    for end in range(n):
        freq[nums[end]] += 1

        if freq[nums[end]] == k + 1:
            violations += 1

        if violations:
            freq[nums[start]] -= 1
            if freq[nums[start]] == k:
                violations -= 1
            start += 1

    return n - start
